{
  "name": "${INSTANCE_NAME}",
  "machineType": "zones/${ZONE}/machineTypes/n1-standard-8",
  "disks": [
    {
      "boot": true,
      "initializeParams": {
        "sourceImage": "projects/ubuntu-os-cloud/global/images/family/ubuntu-2004-lts"
      },
      "autoDelete": true,
      "diskSizeGb": 100
    }
  ],
  "guestAccelerator": [
    {
      "acceleratorCount": 1,
      "acceleratorType": "projects/${PROJECT_ID}/zones/${ZONE}/acceleratorTypes/nvidia-tesla-a6000"
    }
  ],
  "networkInterfaces": [
    {
      "network": "global/networks/default",
      "accessConfigs": [
        {
          "type": "ONE_TO_ONE_NAT",
          "name": "External NAT"
        }
      ]
    }
  ],
  "serviceAccounts": [
    {
      "email": "default",
      "scopes": [
        "https://www.googleapis.com/auth/cloud-platform"
      ]
    }
  ],
  "metadata": {
    "items": [
      {
        "key": "enable-oslogin",
        "value": "TRUE"
      }
    ]
  }
}

Also need to enable GPUs via gcloud compute accelerator-types list. But we assume it's available.

